/**
 * Get Color Type.
 *
 * Retrieves color type from CSS color string. Supports HEX, RGB and HSL color types.
 *
 * @since ??
 *
 * @param {string} color Color string.
 *
 * @returns {string} The matched color type in string, else `undefined`.
 *
 * @example
 * ```ts
 * getColorType('#fff');
 * // 'hex'
 *
 * getColorType('rgb(255, 255, 255)');
 * // 'rgb'
 *
 * getColorType('rgba(255, 255, 255, 1)');
 * // 'rgb'
 *
 * getColorType('hsl(0, 0%, 100%)');
 * // 'hsl'
 *
 * getColorType('hsla(0, 0%, 100%, 1)');
 * // 'hsl'
 * getColorType('invalid');
 * // undefined
 * ```
 */
export declare const getColorType: (color: string) => 'hex' | 'rgb' | 'hsl';
